import { z } from "zod";

export const createUploadInputSchema = z.object({
  name: z.string().trim().min(1).max(255),
  mimeType: z.literal("application/pdf"),
  fileSize: z.number().int().positive().lt(20 * 1024 * 1024),
});

export const finalizeUploadInputSchema = createUploadInputSchema.extend({
  // Preserve the exact S3 key; only accept the format generated by createUpload.
  key: z.string().max(1024)
    .refine((key) => Buffer.byteLength(key, "utf8") <= 1024, "Key must be at most 1024 UTF-8 bytes")
    .regex(/^documents\/[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$/, "Invalid document upload key"),
}).strict();
